	private static SlotPlan weightedLeft(long weight) {
		return new SlotPlan() {
			@Override
			public RowCursor open(RowState row) {
				return weightedRow(row, weight, 0, 1L);
			}

			@Override
			public BatchCursor openBatch(RowState row, int capacity) {
				return new WeightedBatchCursor() {
					boolean emitted;

					@Override
					public int fill(NativeBatch batch) {
						batch.clear();
						if (emitted) {
							return 0;
						}
						emitted = true;
						batch.copyFromRow(row.slots, 0);
						batch.set(0, 0, 1L);
						batch.finishRows(1);
						return 1;
					}

					@Override
					public long weight(int physicalRow) {
						return weight;
					}

					@Override
					public void close() {
					}
				};
			}

			@Override
			public long producedMask() {
				return 1L;
			}
		};
	}

	private static RowCursor weightedRow(RowState row, long weight, int slot, long value) {
		return new FactorizedRowCursor() {
			final int mark = row.mark();
			boolean emitted;

			@Override
			public boolean next() {
				if (emitted) {
					row.rollback(mark);
					return false;
				}
				emitted = true;
				return row.bind(slot, value);
			}

			@Override
			public long multiplicity() {
				return weight;
			}

			@Override
			public void close() {
				row.rollback(mark);
			}
		};
	}

